// PrunePlans implements mm_repository.PlanRepository
func (mmPrunePlans *PlanRepositoryMock) PrunePlans(ctx context.Context, keep int) (err error) {
	mm_atomic.AddUint64(&mmPrunePlans.beforePrunePlansCounter, 1)
	defer mm_atomic.AddUint64(&mmPrunePlans.afterPrunePlansCounter, 1)

	mmPrunePlans.t.Helper()

	if mmPrunePlans.inspectFuncPrunePlans != nil {
		mmPrunePlans.inspectFuncPrunePlans(ctx, keep)
	}

	mm_params := PlanRepositoryMockPrunePlansParams{ctx, keep}

	// Record call args
	mmPrunePlans.PrunePlansMock.mutex.Lock()
	mmPrunePlans.PrunePlansMock.callArgs = append(mmPrunePlans.PrunePlansMock.callArgs, &mm_params)
	mmPrunePlans.PrunePlansMock.mutex.Unlock()

	for _, e := range mmPrunePlans.PrunePlansMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmPrunePlans.PrunePlansMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmPrunePlans.PrunePlansMock.defaultExpectation.Counter, 1)
		mm_want := mmPrunePlans.PrunePlansMock.defaultExpectation.params
		mm_want_ptrs := mmPrunePlans.PrunePlansMock.defaultExpectation.paramPtrs

		mm_got := PlanRepositoryMockPrunePlansParams{ctx, keep}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmPrunePlans.t.Errorf("PlanRepositoryMock.PrunePlans got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmPrunePlans.PrunePlansMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.keep != nil && !minimock.Equal(*mm_want_ptrs.keep, mm_got.keep) {
				mmPrunePlans.t.Errorf("PlanRepositoryMock.PrunePlans got unexpected parameter keep, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmPrunePlans.PrunePlansMock.defaultExpectation.expectationOrigins.originKeep, *mm_want_ptrs.keep, mm_got.keep, minimock.Diff(*mm_want_ptrs.keep, mm_got.keep))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmPrunePlans.t.Errorf("PlanRepositoryMock.PrunePlans got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmPrunePlans.PrunePlansMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmPrunePlans.PrunePlansMock.defaultExpectation.results
		if mm_results == nil {
			mmPrunePlans.t.Fatal("No results are set for the PlanRepositoryMock.PrunePlans")
		}
		return (*mm_results).err
	}
	if mmPrunePlans.funcPrunePlans != nil {
		return mmPrunePlans.funcPrunePlans(ctx, keep)
	}
	mmPrunePlans.t.Fatalf("Unexpected call to PlanRepositoryMock.PrunePlans. %v %v", ctx, keep)
	return
}

