// When sets expectation for the PlanRepository.UpdateSettings which will trigger the result defined by the following
// Then helper
func (mmUpdateSettings *mPlanRepositoryMockUpdateSettings) When(ctx context.Context, settings model.PlannerSettings) *PlanRepositoryMockUpdateSettingsExpectation {
	if mmUpdateSettings.mock.funcUpdateSettings != nil {
		mmUpdateSettings.mock.t.Fatalf("PlanRepositoryMock.UpdateSettings mock is already set by Set")
	}

	expectation := &PlanRepositoryMockUpdateSettingsExpectation{
		mock:               mmUpdateSettings.mock,
		params:             &PlanRepositoryMockUpdateSettingsParams{ctx, settings},
		expectationOrigins: PlanRepositoryMockUpdateSettingsExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmUpdateSettings.expectations = append(mmUpdateSettings.expectations, expectation)
	return expectation
}

